-- Seed smoke test (T-007). `supabase db reset --local` applied seed.sql (generated by `pnpm db:seed`).
-- Persona auth users exist, are synthetic only, and cannot sign in with a password.
begin;
select plan(9);

select set_eq(
  $$select email::text from auth.users where email like '%@example.test'$$,
  array['owner@example.test', 'admin-technical@example.test', 'finance-operator@example.test',
        'viewer@example.test', 'outsider@example.test'],
  'the five synthetic personas are seeded'
);
select is(
  (select count(*)::int from auth.users where email !~ '^[a-z0-9-]+@example\.test$'),
  0,
  'every auth user email is on the reserved example.test domain'
);
select is(
  (select count(*)::int from auth.users where coalesce(encrypted_password, '') <> ''),
  0,
  'no persona has a password'
);
select is(
  (select count(*)::int from auth.users where raw_app_meta_data ? 'role' or raw_user_meta_data ? 'role'),
  0,
  'no role is stored in auth metadata'
);
select is(
  (select count(*)::int from auth.users where email_confirmed_at is null or confirmation_token is null),
  0,
  'personas are confirmed and have non-null token columns'
);
select set_eq(
  $$select u.email::text from auth.identities i join auth.users u on u.id = i.user_id
    where i.provider = 'email' and i.provider_id = u.id::text and i.email = u.email$$,
  $$select email::text from auth.users where email like '%@example.test'$$,
  'each persona has a matching email identity'
);
select is(
  (select count(distinct id)::int from auth.users where email like '%@example.test'),
  (select count(*)::int from auth.users where email like '%@example.test'),
  'persona ids are distinct'
);
select is(
  (select count(*)::int from auth.users where email like '%@example.test' and created_at <> '2026-01-01 00:00:00+00'),
  0,
  'seeded timestamps use the fixed seed epoch'
);

-- The fence at the top of seed.sql refuses to run when any non-synthetic user exists (here: inside this test's
-- transaction only; rolled back at the end).
insert into auth.users (instance_id, id, aud, role, email)
values ('00000000-0000-0000-0000-000000000000', '11111111-1111-4111-8111-111111111111', 'authenticated', 'authenticated',
        'someone@elsewhere.invalid');
select throws_ok(
  $$do $fence$ begin if exists (select 1 from auth.users where email is null or email not like '%@example.test') then raise exception 'synthetic seed refuses: non-synthetic users present'; end if; end $fence$;$$,
  'P0001',
  'synthetic seed refuses: non-synthetic users present',
  'the seed fence aborts when a non-synthetic user exists'
);

select * from finish();
rollback;
